// Calcola il range della settimana precedente (lunedì-domenica)
const now = new Date();

// Trova il lunedì della settimana corrente
const dayOfWeek = now.getDay(); // 0=Dom, 1=Lun, ..., 6=Sab
const daysToThisMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

// Lunedì della settimana scorsa = questo lunedì - 7 giorni
const lastMonday = new Date(now);
lastMonday.setDate(now.getDate() - daysToThisMonday - 7);
lastMonday.setHours(0, 0, 0, 0);

// Domenica della settimana scorsa = lunedì scorso + 6 giorni
const lastSunday = new Date(lastMonday);
lastSunday.setDate(lastMonday.getDate() + 6);
lastSunday.setHours(23, 59, 59, 999);

const formatDate = (d) => d.toISOString().split('T')[0];

const formatDateIT = (d) => {
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
};

return [{
  json: {
    startDate: formatDate(lastMonday),
    endDate: formatDate(lastSunday),
    startDateIT: formatDateIT(lastMonday),
    endDateIT: formatDateIT(lastSunday),
    weekDescription: `dal ${formatDateIT(lastMonday)} al ${formatDateIT(lastSunday)}`,
    weekLabel: `Settimana ${formatDate(lastMonday)} / ${formatDate(lastSunday)}`
  }
}];

// ============================================================
// CONFIGURAZIONE: aggiorna questi siti con quelli forniti
// ============================================================
const sitiRiferimento = [
  'qualenergia.it',
  'rinnovabili.it',
  'pv-magazine.com',
  'electrek.co',
  'energymonitor.ai',
  'renewablesnow.com',
  'rechargenews.com',
  'energeia.it'
  // Aggiungere qui i siti forniti dall'utente
];
// ============================================================

const dateData = $input.first().json;
const { weekDescription, startDate, endDate } = dateData;

const sitiStr = sitiRiferimento.join(', ');

const userQuery = `Trova e analizza i 20 articoli più rilevanti e importanti sulla transizione energetica e le energie rinnovabili pubblicati ${weekDescription}.

Siti di riferimento preferenziali: ${sitiStr}

Focalizzati su:
- Energie rinnovabili (solare, eolico, idroelettrico, geotermico, offshore)
- Storage energetico e batterie
- Politiche energetiche (UE, Italia, mondo)
- Mercati dell'energia, prezzi e investimenti
- Nuove tecnologie e innovazioni del settore
- Grandi aziende e progetti del settore
- Normative e regolamenti europei

Per ogni articolo fornisci:
1. Titolo dell'articolo
2. URL diretto
3. Data di pubblicazione
4. Riassunto di 2-3 frasi
5. Perché è importante per il settore

Elenca in ordine di rilevanza e impatto. Includi SOLO articoli pubblicati ${weekDescription}. Massimo 20 articoli.`;

const requestBody = JSON.stringify({
  model: 'sonar-pro',
  messages: [
    {
      role: 'system',
      content: 'Sei un esperto analista del settore energia e transizione ecologica. Rispondi sempre in italiano. Fornisci informazioni accurate con fonti verificabili. Sii conciso ma completo.'
    },
    {
      role: 'user',
      content: userQuery
    }
  ],
  max_tokens: 4000,
  temperature: 0.1,
  return_citations: true,
  return_images: false,
  search_recency_filter: 'week'
});

return [{
  json: {
    requestBody,
    weekDescription,
    startDate,
    endDate,
    siti: sitiRiferimento
  }
}];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '';
const citations = response.citations || [];

// Estrai date context dal nodo precedente nella catena
const dateData = $('Calcola Date Settimana Precedente').first().json;
const { weekDescription, startDate, endDate } = dateData;

// Estrai fino a 20 link unici dalle citazioni Perplexity
const uniqueLinks = [...new Set(citations)].slice(0, 20);

// Prepara il prompt per Claude
const claudePrompt = `Sei un esperto analista del settore energia e transizione ecologica. Analizza le seguenti notizie della settimana ${weekDescription} sulla transizione energetica e le energie rinnovabili.

=== CONTENUTO RICERCA PERPLEXITY ===
${content}

=== LINK ARTICOLI TROVATI (${uniqueLinks.length} link) ===
${uniqueLinks.map((url, i) => `${i + 1}. ${url}`).join('\n')}

=== ISTRUZIONI ===
Crea un report professionale in italiano con questa struttura HTML:

<h2>📊 Sommario Esecutivo</h2>
(3-4 frasi sui temi principali e le tendenze più importanti della settimana)

<h2>🏆 Articoli Più Importanti</h2>
(Per i 5-8 articoli più rilevanti, includi per ciascuno:)
- Titolo in grassetto con link
- Perché è importante (1-2 frasi)
- Punti chiave (2-3 bullet)

<h2>📈 Trend della Settimana</h2>
(2-3 tendenze emergenti identificate)

<h2>🔮 Da Tenere d'Occhio</h2>
(2-3 sviluppi futuri da monitorare nella prossima settimana)

Usa HTML pulito, professionale e leggibile su client email. Non usare stili inline pesanti - solo tag semantici (h2, h3, p, ul, li, a, strong, em).`;

const claudeRequestBody = JSON.stringify({
  model: 'claude-opus-4-6',
  max_tokens: 4096,
  messages: [
    {
      role: 'user',
      content: claudePrompt
    }
  ]
});

return [{
  json: {
    contenutoPerplexity: content,
    links: uniqueLinks,
    numeroLink: uniqueLinks.length,
    weekDescription,
    startDate,
    endDate,
    claudeRequestBody
  }
}];

const claudeResponse = $input.first().json;
const reportContent = claudeResponse.content?.[0]?.text || '<p>Report non disponibile.</p>';

// Recupera contesto dalla chain
const citazioniData = $('Estrai Citazioni e Prepara Analisi Claude').first().json;
const { weekDescription, numeroLink, links } = citazioniData;

// Data corrente per l'intestazione
const today = new Date();
const dateFormatted = today.toLocaleDateString('it-IT', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

// Capitalizza la prima lettera
const dateCap = dateFormatted.charAt(0).toUpperCase() + dateFormatted.slice(1);

// Lista link come sezione aggiuntiva
const linksHTML = links.length > 0
  ? `<div style="background:#f0faf4;border-left:4px solid #2e9e5b;padding:16px 20px;margin:24px 0;border-radius:0 8px 8px 0">
      <h3 style="color:#1a6b3c;margin-top:0">🔗 Tutti i Link Trovati (${numeroLink})</h3>
      <ol style="margin:0;padding-left:20px">
        ${links.map(url => `<li style="margin-bottom:6px"><a href="${url}" style="color:#1a6b3c;word-break:break-all">${url}</a></li>`).join('')}
      </ol>
    </div>`
  : '';

const emailHTML = `<!DOCTYPE html>
<html lang="it">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Rassegna Settimanale Energia</title>
</head>
<body style="margin:0;padding:0;background:#f0f4f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f0f4f0;padding:20px 0">
<tr><td align="center">
<table width="680" cellpadding="0" cellspacing="0" style="background:white;border-radius:12px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.1)">
  <!-- Header -->
  <tr><td style="background:linear-gradient(135deg,#1a5c35,#2e9e5b);padding:36px 40px;text-align:center">
    <div style="font-size:40px;margin-bottom:12px">🌱</div>
    <h1 style="margin:0;color:white;font-size:26px;font-weight:700">Rassegna Settimanale Energia</h1>
    <p style="margin:8px 0 0;color:rgba(255,255,255,0.85);font-size:14px">Transizione Energetica &amp; Rinnovabili</p>
    <div style="display:inline-block;background:rgba(255,255,255,0.2);padding:6px 16px;border-radius:20px;color:white;font-size:12px;margin-top:12px">
      ${dateCap} · Settimana ${weekDescription}
    </div>
  </td></tr>
  <!-- Body -->
  <tr><td style="padding:36px 40px;color:#333;line-height:1.7;font-size:15px">
    ${reportContent}
    ${linksHTML}
  </td></tr>
  <!-- Footer -->
  <tr><td style="background:#f8f9fa;padding:20px 40px;text-align:center;border-top:1px solid #e8f5e9">
    <p style="margin:0;color:#888;font-size:12px">Report generato automaticamente · Perplexity AI + Claude · n8n Workflow</p>
    <p style="margin:6px 0 0;color:#888;font-size:11px">🌱 Transizione Energetica Monitor · ${numeroLink} fonti analizzate</p>
  </td></tr>
</table>
</td></tr>
</table>
</body>
</html>`;

return [{
  json: {
    emailHTML,
    emailSubject: `🌱 Rassegna Energia ${weekDescription} · ${numeroLink} articoli`,
    weekDescription,
    numeroLink
  }
}];
